    <div class="info-grid">
      <div class="info-card"><div class="info-label">📚 المادة</div><div class="info-value">${D.subject}</div></div>
      <div class="info-card"><div class="info-label">🎓 الصف الدراسي</div><div class="info-value">${D.grade}</div></div>
      <div class="info-card full"><div class="info-label">📅 تاريخ الاختبار</div><div class="info-value">${he}</div></div>
    </div>

